using FinanSmart.Api.Data.Context;using FinanSmart.Api.Modules.Admin.Dashboard.DTOs;using FinanSmart.Api.Modules.Admin.Dashboard.Interfaces;using Microsoft.EntityFrameworkCore;namespace FinanSmart.Api.Modules.Admin.Dashboard.Services;public class AdminDashboardService(FinanSmartDbContext db):IAdminDashboardService{public async Task<AdminDashboardDto> GetAsync(){var a=await db.InvestmentApplications.AsNoTracking().ToListAsync();int C(string s)=>a.Count(x=>x.Status.ToString()==s);decimal S(string s)=>a.Where(x=>x.Status.ToString()==s).Sum(x=>x.Amount);return new(){CreditSummary=new(){ActiveCreditTypes=await db.CreditTypes.CountAsync(x=>x.IsActive),ActiveCreditRates=await db.CreditRates.CountAsync(x=>x.IsActive),ActiveCreditCharges=await db.CreditCharges.CountAsync(x=>x.IsActive)},InvestmentSummary=new(){ActiveInvestmentProducts=await db.InvestmentProducts.CountAsync(x=>x.IsActive),ActiveInvestmentRates=await db.InvestmentRates.CountAsync(x=>x.IsActive),ApplicationsCount=a.Count,SubmittedApplications=C("Submitted"),ApprovedApplications=C("Approved"),RejectedApplications=C("Rejected"),TotalRequestedAmount=S("Submitted")+S("Approved")+S("Rejected"),ApprovedInvestmentAmount=S("Approved")},ApplicationSummary=new(){Draft=C("Draft"),PendingDocuments=C("PendingDocuments"),PendingIdentityVerification=C("PendingIdentityVerification"),ReadyForReview=C("ReadyForReview"),Submitted=C("Submitted"),Approved=C("Approved"),Rejected=C("Rejected"),Cancelled=C("Cancelled"),PendingReviewCount=C("Submitted")},InvestmentApplicationsByStatus=a.GroupBy(x=>x.Status.ToString()).Select(g=>new DashboardStatusDto{Status=g.Key,Count=g.Count()}).ToList(),InvestmentApplicationsByProduct=a.GroupBy(x=>x.InvestmentProductName).Select(g=>new DashboardProductDto{ProductName=g.Key,Count=g.Count(),TotalAmount=g.Sum(x=>x.Amount)}).ToList(),RecentApplications=a.OrderByDescending(x=>x.SubmittedAt??x.CreatedAt).Take(6).Select(x=>new RecentApplicationDto{Id=x.Id,ApplicationNumber=x.ApplicationNumber,ApplicantFullName=$"{x.ApplicantFirstName} {x.ApplicantLastName}".Trim(),InvestmentProductName=x.InvestmentProductName,Amount=x.Amount,Status=x.Status.ToString(),SubmittedAt=x.SubmittedAt,CreatedAt=x.CreatedAt}).ToList()};}}
